// Offline inspection follows the ordinary terrain resource and scene owners.
// The fixture is generated by scripts/voxel-preview.escript, never in the browser.
import { Engine } from '@babylonjs/core/Engines/engine.js'
import { Scene } from '@babylonjs/core/scene.js'
import { ArcRotateCamera } from '@babylonjs/core/Cameras/arcRotateCamera.js'
import { Vector3 } from '@babylonjs/core/Maths/math.vector.js'
import { Color4 } from '@babylonjs/core/Maths/math.color.js'
import { HemisphericLight } from '@babylonjs/core/Lights/hemisphericLight.js'
import { DirectionalLight } from '@babylonjs/core/Lights/directionalLight.js'
import { createRenderResources } from '../src/render-resources.js'
import { readMarks } from '../src/marks.js'
import { paintMarks, paintBodyPoses, paintTerrain } from '../src/scene.js'

const canvas = document.getElementById('terrain'), status = document.getElementById('status')
const engine = new Engine(canvas, true), scene = new Scene(engine)
scene.useRightHandedSystem = true
scene.clearColor = new Color4(0.24, 0.32, 0.35, 1)
const camera = new ArcRotateCamera('inspection', -Math.PI / 2.9, 1.05, 77, new Vector3(0, 3, 0), scene)
camera.minZ = 0.05; camera.lowerRadiusLimit = 2; camera.upperRadiusLimit = 120
camera.wheelPrecision = 8; camera.attachControl(canvas, true)
const fill = new HemisphericLight('sky', new Vector3(0, 1, 0), scene)
fill.intensity = 0.6; fill.groundColor.set(0.24, 0.28, 0.32)
const sun = new DirectionalLight('sun', new Vector3(-0.6, -1, 0.4), scene)
sun.intensity = 2.1
const resources = createRenderResources(scene)
let painted = new Map(), fixture, busy = false, excavated = false
const initial = new URLSearchParams(location.search)
engine.runRenderLoop(() => scene.render())
window.addEventListener('resize', () => engine.resize())
window.voxelSnapshot = () => {
  scene.render()
  return { image: canvas.toDataURL('image/png'), status: status.textContent }
}
for (const button of document.querySelectorAll('[data-view]')) button.onclick = () => {
  const views = { overview: [-Math.PI / 2.9, 1.05, 77, [0, 3, 0]],
    cave: [Math.PI, 1.48, 32, [-11, 3, 0]], dig: [-Math.PI / 2, 0.55, 30, [11, 5, -7]] }
  const [alpha, beta, radius, target] = views[button.dataset.view]
  camera.setTarget(Vector3.FromArray(target)); camera.alpha = alpha; camera.beta = beta; camera.radius = radius
}
document.getElementById('wireframe').onclick = event => {
  const enabled = event.currentTarget.getAttribute('aria-pressed') !== 'true'
  event.currentTarget.setAttribute('aria-pressed', String(enabled))
  for (const material of scene.materials) material.wireframe = enabled
}
document.getElementById('dig').onclick = async event => {
  if (busy || !fixture) return
  const button = event.currentTarget
  busy = true; excavated = !excavated
  try { await show(excavated); button.setAttribute('aria-pressed', String(excavated)) }
  catch (error) { status.textContent = String(error); throw error }
  finally { busy = false }
}
async function show(edited) {
  const rows = fixture[edited ? 'after' : 'before']
  const terrain = new Map(rows.map(row => [`0:${row.chunk.join(',')}`, { ...row,
    body: '0', revision: '1', spacing_mm: fixture.spacing_mm,
    payload: Uint8Array.from(atob(row.payload), c => c.charCodeAt(0)),
    costs: [16 + 38 * row.triangles, 108 * row.triangles, 3 * row.triangles, row.triangles, 1],
  }]))
  const poses = new Map([['0:1', { body: '0', revision: '1', position: [0, 0, 0], rotation: [0, 0, 0, 1] }]])
  paintBodyPoses(painted, poses)
  await paintTerrain(scene, painted, { terrain, poses, origin: [0n, 0n, 0n], terrainReady: true }, resources,
    error => { status.textContent = String(error) })
  await scene.whenReadyAsync(); scene.render()
  const triangles = rows.reduce((n, row) => n + row.triangles, 0)
  status.textContent = `${edited ? 'Excavated' : 'Original'} · ${triangles.toLocaleString()} triangles · 1 m samples · ${fixture.changed_chunks} chunks changed by digging`
  return { triangles, chunks: rows.length, edited, meshes: scene.meshes.length }
}
window.voxelReady = (async () => {
  const response = await fetch('./fixtures/voxel-preview.json')
  if (!response.ok) throw new Error(`Fixture unavailable: ${response.status}`)
  fixture = await response.json()
  const textures = ['25ebb5a3408f3a17e80ee1d56fc1290c945076ee648aacb8ac5ff6a0725fc46c','e3637cbd17d1f086f32ebdf21c8399b0bac9d6dccecae1bd2207482895e17678']
  const palette = fixture.palette.map(([id, colour]) => {
    const digest = textures[id === 1 ? 0 : 1]
    const tint = id === 1 ? '#B7D6AA' : colour
    return `material(${id},surface(<<"${tint}">>,0,900,0,[texture(<<"base_colour">>,asset(<<"${digest}">>,<<"image/jpeg">>),repeat(500,500))]))`
  }).join(',')
  const marks = readMarks(`[mark(<<"terrain">>,<<"terrain">>,terrain_geometry(<<"qvt1">>,[${palette}],view_distance(20000,8000,8000),resources(4000000,8000000,100000,50000,512)),body_pose(0,1),terrain_surfaces,unlabelled,depicts(<<"preview">>,<<"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa">>,land))]`)
  painted = paintMarks(scene, marks, painted, resources)
  excavated = initial.get('excavated') === 'true'
  document.getElementById('dig').setAttribute('aria-pressed', String(excavated))
  const view = [...document.querySelectorAll('[data-view]')].find(button => button.dataset.view === initial.get('view'))
  view?.click()
  return show(excavated)
})().catch(error => { status.textContent = `Preview unavailable: ${error.message}`; throw error })
